/*
 * A244961  Decimal equivalent of the binary string generated by the n X n
 *          antidiagonal matrix read by rows.
 * https://oeis.org/A244961
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = Sum_{k=1..n} 2^((n-1)*k)
 * Range:     u8 n <= 2, u16 n <= 4, u32 n <= 5, u64 n <= 8, u128 n <= 11,
 *            big any n
 * Helpers:   pow2
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include "../utils/pow2.h"

seq_t a(idx_t n)
{
    if (n == 1) return 1;

    /* 2^n and 2^(n^2) */
    seq_t pow2n  = pow2(n);
    seq_t pow2n2 = pow2(n * n);

    seq_t numerator   = pow2n2 - pow2n;
    seq_t denominator = pow2n - (seq_t)2;

    return numerator / denominator;
}
